import React, { useState, useEffect } from 'react';
import { Header } from '@/components/layout/Header';
import { Sidebar, AppPageId } from '@/components/layout/Sidebar';
import { QuestionBankView } from '@/app/(dashboard)/questions/page';
import { ExamPapersView } from '@/app/(dashboard)/exams/page';
import { SystemSettingsView } from '@/app/(auth)/profile/page';
import { AccountManagementView } from '@/app/(dashboard)/users/page';
import { UserSettingsView } from '@/app/(auth)/profile/_components/UserSettingsView';
import { ExamPaperSelection } from '@/app/(dashboard)/exams/select/_components/ExamPaperSelection';
import QuestionSelectorPage from '@/app/(dashboard)/selector/page';
import WrongQuestionsPage from '@/app/(dashboard)/wrong-questions/page';
import { LoginPage } from '@/app/(auth)/login/page';
import RegisterPage from '@/app/(auth)/register/page';
import { TwoPhaseDeleteModal, DeleteItem } from '@/components/common/TwoPhaseDeleteModal';
import { ExamGenerationModal } from '@/app/(dashboard)/exams/_components/ExamFormModal';
import { QuestionDetailModal } from '@/app/(dashboard)/questions/_components/QuestionDetailModal';
import { CreateQuestionModal } from '@/app/(dashboard)/questions/_components/QuestionModal';
import { UploadExamModal } from '@/app/(dashboard)/questions/_components/UploadExamModal';
import { ExamPaperPreviewModal } from '@/app/(dashboard)/exams/_components/ExamPaperPreviewModal';
import { GlobalSearchModal } from '@/components/layout/GlobalSearchModal';
import { Question, ExamPaper, Exam, SubjectId, SubjectFilter, AuditLog, NotificationItem, CategoryItem, UserProfile, RoleItem } from '@/types';
import { ExamClient } from '@/app/exam/[examId]/_components/ExamClient';
import {
  getEnvConfiguredSpreadsheetUrl,
  getEnvConfiguredScriptUrl,
  extractSpreadsheetId,
  fetchSpreadsheetStats,
  syncAllToSpreadsheet,
  readAllTablesFromSpreadsheet,
  appendQuestionToSpreadsheet,
  appendExamToSpreadsheet,
  appendLogToSpreadsheet,
  syncExamsOnlyToSpreadsheet,
  deleteRowsFromSpreadsheetViaGas,
  formatSheetTimestamp,
  appendUserToSpreadsheet,
  getAssignedExam,
} from '@/services/publicSheet';
import { getAccessToken, googleSignIn, initAuth } from '@/services/googleAuth';
import { downloadFullOfflinePack } from '@/services/excelDatabaseExport';
import { SyncConflictModal, ConflictDetails } from '@/components/common/SyncConflictModal';
import { readUserPrivateSheet, syncPersonalDataToUserSheet } from '@/services/userSheet';

export default function App() {
  const [currentUser, setCurrentUser] = useState<UserProfile | null>(() => {
    if (typeof window === 'undefined') return null;
    try {
      const saved = sessionStorage.getItem('exam_logged_in_user');
      return saved ? (JSON.parse(saved) as UserProfile) : null;
    } catch {
      return null;
    }
  });
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const currentOperatorName = currentUser
    ? `${currentUser.name || currentUser.nickname} (${currentUser.role})`
    : '未登入訪客';

  // 判定是否為管理員，非管理員角色一律在 else 處理為使用者
  const roleCode = String(currentUser?.role || '').toUpperCase();
  const isAdmin = roleCode === 'ADMIN';

  // 預設路由：管理員介面預設導向「題目選擇 (question-bank / selector)」，使用者介面預設導向「試卷選擇 (user-exam-select)」
  const [activePage, setActivePage] = useState<AppPageId>(() => {
    if (isAdmin) {
      return 'question-bank';
    } else {
      return 'user-exam-select';
    }
  });

  const [selectedSubject, setSelectedSubject] = useState<SubjectFilter>('all');
  const [collapsedSidebar, setCollapsedSidebar] = useState(false);

  // Users & Roles state for Account Management (table: users, table: roles)
  const [usersList, setUsersList] = useState<UserProfile[]>([]);
  const [rolesList, setRolesList] = useState<RoleItem[]>([]);

  // 離線打包與雙向衝突狀態
  const [isDownloadingOfflinePack, setIsDownloadingOfflinePack] = useState(false);
  const [conflictModalOpen, setConflictModalOpen] = useState(false);
  const [currentConflict, setCurrentConflict] = useState<ConflictDetails | null>(null);
  const [isResolvingConflict, setIsResolvingConflict] = useState(false);
  const [pendingRemoteData, setPendingRemoteData] = useState<{
    personal?: { questions: Question[]; exams: ExamPaper[] };
    public?: { questions: Question[]; exams: ExamPaper[]; categories: CategoryItem[] };
  }>({});

  // Google Sheets connected spreadsheet state (prioritizing .env if configured, otherwise localStorage)
  const envSheetUrl = getEnvConfiguredSpreadsheetUrl();
  const envSheetId = extractSpreadsheetId(envSheetUrl);

  const [connectedSpreadsheetId, setConnectedSpreadsheetId] = useState<string | null>(() => {
    return (
      envSheetId ||
      (typeof window !== 'undefined' ? localStorage.getItem('google_spreadsheet_id') : null) ||
      null
    );
  });
  const [connectedSpreadsheetUrl, setConnectedSpreadsheetUrl] = useState<string | null>(() => {
    return (
      envSheetUrl ||
      (typeof window !== 'undefined' ? localStorage.getItem('google_spreadsheet_url') : null) ||
      null
    );
  });
  const [isReconnectingSheets, setIsReconnectingSheets] = useState(false);
  const [isSyncingSheets, setIsSyncingSheets] = useState(false);
  const [isLoadingSheetData, setIsLoadingSheetData] = useState(false);
  const [hasSyncedSheet, setHasSyncedSheet] = useState(false);
  const [isOnline, setIsOnline] = useState<boolean>(() =>
    typeof navigator !== 'undefined' ? navigator.onLine : true
  );

  // Data states - directly read from Google Sheets (no hardcoded mock data)
  const [categories, setCategories] = useState<CategoryItem[]>([]);
  const [questions, setQuestions] = useState<Question[]>([]);
  const [selectedQuestionIds, setSelectedQuestionIds] = useState<string[]>([]);

  const [examPapers, setExamPapers] = useState<ExamPaper[]>([]);
  const [selectedExamIds, setSelectedExamIds] = useState<string[]>([]);

  const handleUpdateSpreadsheetConnection = (id: string | null, url: string | null) => {
    setConnectedSpreadsheetId(id);
    setConnectedSpreadsheetUrl(url);
    if (id && url) {
      localStorage.setItem('google_spreadsheet_id', id);
      localStorage.setItem('google_spreadsheet_url', url);
    } else {
      localStorage.removeItem('google_spreadsheet_id');
      localStorage.removeItem('google_spreadsheet_url');
      setHasSyncedSheet(false);
      setCategories([]);
      setQuestions([]);
      setExamPapers([]);
      setAuditLogs([]);
    }
  };

  const recordAuditLog = async (logEntry: AuditLog, explicitToken?: string | null) => {
    setAuditLogs((prev) => [logEntry, ...prev]);

    const targetId = envSheetId || connectedSpreadsheetId;
    if (!targetId) return;

    try {
      const hasGas = Boolean(getEnvConfiguredScriptUrl());
      const token = explicitToken || (await getAccessToken());
      if (hasGas || token) {
        const nextRowIdx = auditLogs.length + 1;
        await appendLogToSpreadsheet(token, targetId, logEntry, nextRowIdx);
      }
    } catch (err) {
      console.warn('Failed to write audit log to Google Sheet log tab:', err);
    }
  };

  const handleDownloadOfflinePack = async () => {
    setIsDownloadingOfflinePack(true);
    try {
      showToast('正在打包公用題庫 (唯讀) 與個人題庫 (可編) Excel 檔案...', 'info');

      let personalQuestions: Question[] = [];
      let personalExams: ExamPaper[] = [];
      if (typeof window !== 'undefined') {
        try {
          personalQuestions = JSON.parse(localStorage.getItem('quiz_custom_questions') || '[]');
          personalExams = JSON.parse(localStorage.getItem('quiz_custom_exams') || '[]');
        } catch {}
      }

      await downloadFullOfflinePack({
        publicData: {
          categories: categories,
          questions: questions,
          publishedExams: examPapers,
          roles: rolesList,
          auditLogs: auditLogs,
        },
        personalData: {
          questions: personalQuestions,
          exams: personalExams,
        },
        currentUser: currentUser,
      });

      showToast('🎉 離線版本下載完成！已打包「公用題庫 (唯讀)」與「個人題庫 (可編)」兩份 Excel。', 'success');
    } catch (err: any) {
      console.error('Download offline pack error:', err);
      showToast(`下載離線版本失敗: ${err.message || '未知錯誤'}`, 'error');
    } finally {
      setIsDownloadingOfflinePack(false);
    }
  };

  /**
   * 雙向連線同步與衝突比對：
   * 1. 個人題庫比對 (若有綁定個人 Google Sheet)
   * 2. 公用題庫比對
   */
  const handleBidirectionalSync = async (silent: boolean = false) => {
    if (typeof navigator !== 'undefined' && !navigator.onLine) {
      setIsOnline(false);
      setHasSyncedSheet(false);
      if (!silent) showToast('目前處於離線狀態，無法進行線上同步與比對', 'warning');
      return;
    }

    const targetUrl = envSheetUrl || connectedSpreadsheetUrl;
    const targetId = envSheetId || connectedSpreadsheetId;
    let token = await getAccessToken();

    setIsLoadingSheetData(true);
    try {
      // 1. 個人題庫比對 (若有綁定個人 Google Sheet)
      if (currentUser?.google_sheet_URL) {
        if (!token && !silent) {
          try {
            const signRes = await googleSignIn();
            token = signRes?.accessToken || null;
          } catch {}
        }

        if (token) {
          try {
            const remotePersonal = await readUserPrivateSheet(token, currentUser.google_sheet_URL);
            const remoteQuestions = remotePersonal.questions || [];
            const remoteExams = remotePersonal.publishedExams || [];

            let localQuestions: Question[] = [];
            let localExams: ExamPaper[] = [];
            if (typeof window !== 'undefined') {
              try {
                localQuestions = JSON.parse(localStorage.getItem('quiz_custom_questions') || '[]');
                localExams = JSON.parse(localStorage.getItem('quiz_custom_exams') || '[]');
              } catch {}
            }

            const isQuestionsMatch =
              localQuestions.length === remoteQuestions.length &&
              JSON.stringify(localQuestions.map((q) => q.id).sort()) ===
                JSON.stringify(remoteQuestions.map((q) => q.id).sort());

            const isExamsMatch =
              localExams.length === remoteExams.length &&
              JSON.stringify(localExams.map((e) => e.id).sort()) ===
                JSON.stringify(remoteExams.map((e) => e.id).sort());

            if (!isQuestionsMatch || !isExamsMatch) {
              // 發現差異！彈出個人題庫衝突對話框
              setPendingRemoteData((prev) => ({
                ...prev,
                personal: { questions: remoteQuestions, exams: remoteExams },
              }));
              setCurrentConflict({
                type: 'personal',
                title: '個人題庫雙向比對衝突',
                localSummary: {
                  questionCount: localQuestions.length,
                  examCount: localExams.length,
                },
                remoteSummary: {
                  questionCount: remoteQuestions.length,
                  examCount: remoteExams.length,
                },
              });
              setConflictModalOpen(true);
              return;
            }
          } catch (pErr) {
            console.warn('Compare personal sheet error:', pErr);
          }
        }
      }

      // 2. 公用題庫比對
      if (!targetId) {
        if (!silent) showToast('未設定公用 Google 試算表 ID', 'warning');
        return;
      }

      const remotePublic = await readAllTablesFromSpreadsheet(token, targetId);
      setIsOnline(true);
      setHasSyncedSheet(true);

      // 比對公用題庫線上 vs 本地
      const isPublicMatch =
        remotePublic.questions.length === questions.length &&
        remotePublic.allExams.length === examPapers.length;

      if (!isPublicMatch && questions.length > 0 && !silent) {
        // 線上與本地公用題庫不同，詢問是否更新本地公用題庫
        setPendingRemoteData((prev) => ({
          ...prev,
          public: {
            questions: remotePublic.questions,
            exams: remotePublic.allExams,
            categories: remotePublic.categories,
          },
        }));
        setCurrentConflict({
          type: 'public',
          title: '公用題庫線上版本更新確認',
          localSummary: {
            questionCount: questions.length,
            examCount: examPapers.length,
          },
          remoteSummary: {
            questionCount: remotePublic.questions.length,
            examCount: remotePublic.allExams.length,
          },
        });
        setConflictModalOpen(true);
        return;
      }

      // 若一致或初次靜默加載，直接更新最新線上資料
      setCategories(remotePublic.categories);
      if (remotePublic.questions?.length > 0) setQuestions(remotePublic.questions);
      if (remotePublic.allExams?.length > 0) setExamPapers(remotePublic.allExams);
      setAuditLogs(remotePublic.auditLogs);
      if (remotePublic.users?.length > 0) setUsersList(remotePublic.users);
      if (remotePublic.roles?.length > 0) setRolesList(remotePublic.roles);
      handleUpdateSpreadsheetConnection(targetId, targetUrl);

      if (!silent) {
        showToast('✅ 公用與個人資料庫比對完成，資料已同步至最新狀態！', 'success');
      }
    } catch (err: any) {
      console.error('Bidirectional sync error:', err);
      if (!silent) {
        showToast(`連線比對失敗: ${err.message || '請確認試算表網址或權限'}`, 'error');
      }
    } finally {
      setIsLoadingSheetData(false);
    }
  };

  const handleResolvePersonalConflict = async (choice: 'local' | 'remote', updateTarget: boolean) => {
    setIsResolvingConflict(true);
    try {
      if (choice === 'local') {
        // 以本地為主
        if (updateTarget && currentUser?.google_sheet_URL) {
          const token = await getAccessToken();
          if (!token) throw new Error('請先完成 Google 帳號授權以更新個人試算表');
          let localQuestions: Question[] = [];
          let localExams: ExamPaper[] = [];
          try {
            localQuestions = JSON.parse(localStorage.getItem('quiz_custom_questions') || '[]');
            localExams = JSON.parse(localStorage.getItem('quiz_custom_exams') || '[]');
          } catch {}
          await syncPersonalDataToUserSheet(token, currentUser.google_sheet_URL, localQuestions, localExams);
          showToast('✅ 已成功將本地個人題庫同步更新至線上個人 Google Sheet！', 'success');
        } else {
          showToast('已確認以本地個人題庫為主（未更新線上試算表）。', 'info');
        }
      } else {
        // 以線上為主
        if (updateTarget && pendingRemoteData.personal) {
          localStorage.setItem('quiz_custom_questions', JSON.stringify(pendingRemoteData.personal.questions));
          localStorage.setItem('quiz_custom_exams', JSON.stringify(pendingRemoteData.personal.exams));
          showToast('✅ 已從個人 Google Sheet 更新覆蓋本地題庫資料！', 'success');
        } else {
          showToast('已確認以線上個人資料為主。', 'info');
        }
      }
      setConflictModalOpen(false);
      setCurrentConflict(null);
    } catch (err: any) {
      alert(`衝突處理失敗：${err.message || '未知錯誤'}`);
    } finally {
      setIsResolvingConflict(false);
    }
  };

  const handleResolvePublicConflict = async (shouldUpdateLocal: boolean) => {
    setIsResolvingConflict(true);
    try {
      if (shouldUpdateLocal && pendingRemoteData.public) {
        setQuestions(pendingRemoteData.public.questions);
        setExamPapers(pendingRemoteData.public.exams);
        setCategories(pendingRemoteData.public.categories);
        // 更新本地離線快取
        try {
          localStorage.setItem(
            'offline_public_db_cache',
            JSON.stringify({
              questions: pendingRemoteData.public.questions,
              publishedExams: pendingRemoteData.public.exams,
              categories: pendingRemoteData.public.categories,
              downloadedAt: new Date().toISOString(),
            })
          );
        } catch {}
        showToast('✅ 本地公用題庫已更新至線上最新版本！', 'success');
      } else {
        showToast('已保留本機現有公用題庫版本。', 'info');
      }
      setConflictModalOpen(false);
      setCurrentConflict(null);
    } finally {
      setIsResolvingConflict(false);
    }
  };

  const handleFetchSpreadsheetData = async (silent: boolean = false) => {
    await handleBidirectionalSync(silent);
  };

  useEffect(() => {
    const handleOnline = () => {
      setIsOnline(true);
      handleBidirectionalSync(true);
    };
    const handleOffline = () => {
      setIsOnline(false);
      setHasSyncedSheet(false);
      // 網路斷線時自動切換至 local 離線題庫快照備援
      try {
        const cached = localStorage.getItem('offline_public_db_cache');
        if (cached) {
          const parsed = JSON.parse(cached);
          if (parsed.questions?.length > 0) setQuestions(parsed.questions);
          if (parsed.publishedExams?.length > 0) setExamPapers(parsed.publishedExams);
          if (parsed.categories?.length > 0) setCategories(parsed.categories);
        } else {
          setQuestions([]);
          setExamPapers([]);
          setCategories([]);
        }
      } catch {
        setQuestions([]);
        setExamPapers([]);
        setCategories([]);
      }
      showToast('偵測到網路斷線，已切換至本地離線題庫 (公用唯讀，個人可編)', 'warning');
    };

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [questions.length, examPapers.length]);

  useEffect(() => {
    const unsubscribe = initAuth((_user, token) => {
      if (token) {
        handleFetchSpreadsheetData(true);
      }
    });
    return () => {
      if (unsubscribe) unsubscribe();
    };
  }, []);

  // Automatically read spreadsheet upon entering any page (question-bank, exam-papers, etc.)
  useEffect(() => {
    handleFetchSpreadsheetData(true);
  }, [activePage]);

  const handleReconnectSheets = async () => {
    setIsReconnectingSheets(true);
    try {
      const targetUrl = connectedSpreadsheetUrl || envSheetUrl;
      const targetId = connectedSpreadsheetId || envSheetId;

      if (!targetId || !targetUrl) {
        setHasSyncedSheet(false);
        showToast('未設定 Google 試算表網址，請在 .env 中填寫 NEXT_PUBLIC_GOOGLE_SHEET_URL', 'warning');
        setIsReconnectingSheets(false);
        return;
      }

      let token = await getAccessToken();
      if (!token) {
        const signRes = await googleSignIn();
        token = signRes?.accessToken || null;
      }

      if (!token) {
        setHasSyncedSheet(false);
        showToast('Google 帳號授權未完成或登入已取消', 'warning');
        setIsReconnectingSheets(false);
        return;
      }

      const stats = await fetchSpreadsheetStats(token, targetId);
      handleUpdateSpreadsheetConnection(targetId, targetUrl);

      try {
        const result = await readAllTablesFromSpreadsheet(token, targetId);
        setCategories(result.categories);
        setQuestions((prev) => {
          const remoteIds = new Set(result.questions.map((q) => q.id));
          const localUnsynced = prev.filter((q) => !remoteIds.has(q.id));
          return [...localUnsynced, ...result.questions];
        });
        setExamPapers((prev) => {
          const remoteIds = new Set(result.allExams.map((e) => e.id));
          const localUnsynced = prev.filter((e) => !remoteIds.has(e.id));
          return [...localUnsynced, ...result.allExams];
        });
        setAuditLogs(result.auditLogs);
        setHasSyncedSheet(true);
        setIsOnline(true);
        showToast(`公用資料庫連線成功！已從「${stats.title}」載入 ${result.categories.length} 個科目、${result.questions.length} 題試題及 ${result.allExams.length} 份試卷。`, 'success');
      } catch (readErr: any) {
        setHasSyncedSheet(false);
        showToast(`試算表「${stats.title}」讀取資料表失敗，請確認試算表架構`, 'warning');
      }
    } catch (err: any) {
      console.error('Reconnect error:', err);
      setHasSyncedSheet(false);
      showToast(`連線失敗: ${err.message || '請確認試算表網址或權限'}`, 'error');
    } finally {
      setIsReconnectingSheets(false);
    }
  };

  const handleSyncMockDataToSheets = async () => {
    setIsSyncingSheets(true);
    try {
      const targetUrl = connectedSpreadsheetUrl || envSheetUrl;
      const targetId = connectedSpreadsheetId || envSheetId;

      if (!targetId || !targetUrl) {
        showToast('未設定 Google 試算表網址，請確認 .env 或試算表連結', 'warning');
        setIsSyncingSheets(false);
        return;
      }

      let token = await getAccessToken();
      if (!token) {
        showToast('正在開啟 Google 授權視窗，請允許試算表存取權限...', 'info');
        const signRes = await googleSignIn();
        token = signRes?.accessToken || null;
      }

      if (!token) {
        showToast('Google 帳號授權未完成或登入已取消', 'warning');
        setIsSyncingSheets(false);
        return;
      }

      const questionsToSync = questions;
      const examsToSync = examPapers;

      const now = formatSheetTimestamp();
      const newLogId = `#LOG-SYNC-${Date.now().toString().slice(-4)}`;
      const syncLogEntry: AuditLog = {
        id: newLogId,
        action: '題庫試卷完整同步至 Google 試算表',
        target: `test_bank (${questionsToSync.length} 題), 試卷 (${examsToSync.length} 份)`,
        operator: currentOperatorName,
        timestamp: now,
        status: 'success',
      };
      const logsToSync = [syncLogEntry, ...auditLogs];

      showToast('正在將題目與考卷資料寫入 Google 試算表 (test_bank)...', 'info');
      const result = await syncAllToSpreadsheet(token, targetId, targetUrl, questionsToSync, examsToSync, logsToSync);

      setQuestions(questionsToSync);
      setExamPapers(examsToSync);
      setAuditLogs(logsToSync);
      setHasSyncedSheet(true);
      handleUpdateSpreadsheetConnection(targetId, targetUrl);

      setNotifications((prev) => [
        {
          id: `notif-${Date.now()}`,
          title: `成功將 ${questionsToSync.length} 筆題庫試題寫入 Google 試算表「test_bank」！`,
          time: '剛剛',
          read: false,
          type: 'success',
        },
        ...prev,
      ]);

      showToast(`✅ 成功將 ${questionsToSync.length} 筆題目與考卷寫入 Google 試算表！`, 'success');
    } catch (err: any) {
      console.error('Sync mock data error:', err);
      showToast(`寫入失敗: ${err.message || '請確認試算表網址或權限'}`, 'error');
    } finally {
      setIsSyncingSheets(false);
    }
  };

  const [notifications, setNotifications] = useState<NotificationItem[]>([
    {
      id: 'notif-1',
      title: '高二數學期末統一測驗 已完成自動配分核算',
      time: '10 分鐘前',
      read: false,
      type: 'info',
    },
    {
      id: 'notif-2',
      title: '新題目 Q-MATH-20240902 已通過題目審核委員會核定',
      time: '35 分鐘前',
      read: false,
      type: 'success',
    },
  ]);

  // Audit logs - directly read from and written to Google Sheet "log" tab (no hardcoded mock data)
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]);

  // Modal states
  const [isTwoPhaseDeleteOpen, setIsTwoPhaseDeleteOpen] = useState(false);
  const [deleteTargetType, setDeleteTargetType] = useState<'exam' | 'question'>('exam');
  const [singleItemToDelete, setSingleItemToDelete] = useState<DeleteItem | null>(null);

  const [isExamGenerationOpen, setIsExamGenerationOpen] = useState(false);
  const [previewingQuestion, setPreviewingQuestion] = useState<Question | null>(null);
  const [editingQuestion, setEditingQuestion] = useState<Question | null>(null);
  const [isCreateQuestionOpen, setIsCreateQuestionOpen] = useState(false);
  const [isUploadExamOpen, setIsUploadExamOpen] = useState(false);

  const [previewingExam, setPreviewingExam] = useState<ExamPaper | null>(null);
  const [isGlobalSearchOpen, setIsGlobalSearchOpen] = useState(false);
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  // Global hotkeys: [ for sidebar, ⌘K for search
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') {
        e.preventDefault();
        setIsGlobalSearchOpen(true);
      } else if (e.key === '[' && !(e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement)) {
        e.preventDefault();
        setCollapsedSidebar((prev) => !prev);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  const showToast = (msg: string, _type?: string) => {
    setToastMessage(msg);
    setTimeout(() => setToastMessage(null), 3000);
  };

  // 檢測當前網址是否為作答頁面路由 (/exam/:examId)
  const getInitialExamIdFromUrl = (): string | null => {
    if (typeof window === 'undefined') return null;
    const path = window.location.pathname;
    const match = path.match(/^\/exam\/([^/?#]+)/);
    return match ? decodeURIComponent(match[1]) : null;
  };

  const [takingExamId, setTakingExamId] = useState<string | null>(getInitialExamIdFromUrl);
  const [activeExam, setActiveExam] = useState<Exam | null>(null);
  const [isLoadingExam, setIsLoadingExam] = useState(false);

  useEffect(() => {
    const handlePopState = () => {
      const examId = getInitialExamIdFromUrl();
      setTakingExamId(examId);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  useEffect(() => {
    if (!takingExamId) {
      setActiveExam(null);
      return;
    }
    let isCancelled = false;
    setIsLoadingExam(true);
    getAssignedExam(takingExamId, examPapers, questions).then((exam) => {
      if (isCancelled) return;
      setIsLoadingExam(false);
      if (exam) {
        setActiveExam(exam);
      } else {
        showToast('找不到對應試卷題目或該考卷尚未發布', 'error');
        setTakingExamId(null);
        if (typeof window !== 'undefined' && window.location.pathname.startsWith('/exam/')) {
          window.history.pushState(null, '', '/');
        }
      }
    });
    return () => {
      isCancelled = true;
    };
  }, [takingExamId, examPapers, questions]);

  // Delete modal trigger handlers
  const handleOpenBatchDeleteExams = () => {
    if (!isOnline) {
      showToast('離線模式下公用試卷為唯讀狀態，無法進行刪除操作！', 'warning');
      return;
    }
    setDeleteTargetType('exam');
    setSingleItemToDelete(null);
    setIsTwoPhaseDeleteOpen(true);
  };

  const handleOpenSingleDeleteExam = (exam: ExamPaper) => {
    if (!isOnline && exam.sourceScope !== 'private') {
      showToast('離線模式下公用試卷為唯讀狀態，無法刪除！', 'warning');
      return;
    }
    setDeleteTargetType('exam');
    setSingleItemToDelete({
      id: exam.id,
      title: exam.title,
      extraInfo: exam.status === 'published' ? `已發布 / ${exam.examineeCount || 0}人應試` : `草稿 / ${exam.questionCount}題`,
    });
    setIsTwoPhaseDeleteOpen(true);
  };

  const handleOpenBatchDeleteQuestions = () => {
    if (!isOnline) {
      showToast('離線模式下公用題庫為唯讀狀態，無法進行批次刪除！', 'warning');
      return;
    }
    setDeleteTargetType('question');
    setSingleItemToDelete(null);
    setIsTwoPhaseDeleteOpen(true);
  };

  const handleOpenSingleDeleteQuestion = (q: Question) => {
    if (!isOnline && q.sourceScope !== 'private') {
      showToast('離線模式下公用試題為唯讀狀態，無法刪除！', 'warning');
      return;
    }
    setDeleteTargetType('question');
    setSingleItemToDelete({
      id: q.id,
      title: q.content,
      extraInfo: `${q.points}分 / 難度 ${q.difficultyScore ?? (q.difficulty === 'hard' ? 4 : q.difficulty === 'medium' ? 3 : 2)}`,
    });
    setIsTwoPhaseDeleteOpen(true);
  };

  // Execution of deletion
  const handleConfirmDeletion = async () => {
    const now = formatSheetTimestamp();
    const newLogId = `#LOG-${new Date().getFullYear()}${String(new Date().getMonth() + 1).padStart(2, '0')}-${Math.floor(1000 + Math.random() * 9000)}`;

    if (deleteTargetType === 'exam') {
      const idsToRemove = singleItemToDelete
        ? [singleItemToDelete.id]
        : selectedExamIds;

      setExamPapers((prev) => prev.filter((e) => !idsToRemove.includes(e.id)));
      setSelectedExamIds((prev) => prev.filter((id) => !idsToRemove.includes(id)));

      try {
        await deleteRowsFromSpreadsheetViaGas(
          ['quiz_bank_publish', 'quiz_bank_unpublish'],
          1,
          idsToRemove
        );
      } catch (err) {
        console.warn('Failed to delete exam rows via GAS:', err);
      }

      const logEntry: AuditLog = {
        id: newLogId,
        action: singleItemToDelete ? `單一試卷移除` : `批次試卷刪除`,
        target: idsToRemove.join(', '),
        operator: currentOperatorName,
        timestamp: now,
        status: 'warning',
      };
      await recordAuditLog(logEntry);

      showToast(`已成功移除 ${idsToRemove.length} 份試卷，異動日誌編號 ${newLogId}`);
    } else {
      const idsToRemove = singleItemToDelete
        ? [singleItemToDelete.id]
        : selectedQuestionIds;

      setQuestions((prev) => prev.filter((q) => !idsToRemove.includes(q.id)));
      setSelectedQuestionIds((prev) => prev.filter((id) => !idsToRemove.includes(id)));

      try {
        await deleteRowsFromSpreadsheetViaGas(['test_bank'], 1, idsToRemove);
      } catch (err) {
        console.warn('Failed to delete question rows via GAS:', err);
      }

      const logEntry: AuditLog = {
        id: newLogId,
        action: singleItemToDelete ? `題目刪除` : `批次題目刪除`,
        target: idsToRemove.join(', '),
        operator: currentOperatorName,
        timestamp: now,
        status: 'warning',
      };
      await recordAuditLog(logEntry);

      showToast(`已成功刪除 ${idsToRemove.length} 筆題目，異動日誌編號 ${newLogId}`);
    }
  };

  // Exam published from draft to public table - moves rows in Google Sheets
  const handlePublishExams = async (examIds: string[]) => {
    const updatedExams = examPapers.map((exam) => {
      if (examIds.includes(exam.id)) {
        return {
          ...exam,
          status: 'published' as const,
        };
      }
      return exam;
    });

    setExamPapers(updatedExams);
    setSelectedExamIds((prev) => prev.filter((id) => !examIds.includes(id)));

    const now = formatSheetTimestamp();
    const newLogId = `#LOG-PUB-${Date.now().toString().slice(-4)}`;

    const logEntry: AuditLog = {
      id: newLogId,
      action: `試卷正式發布 (草稿資料表轉移至公用試卷資料表)`,
      target: examIds.join(', '),
      operator: currentOperatorName,
      timestamp: now,
      status: 'success',
    };

    showToast(`已成功將 ${examIds.length} 份試卷正式發布至「公用試卷資料表」！`);

    // Synchronize exam tables and log on Google Sheets
    const targetId = connectedSpreadsheetId || envSheetId;
    const hasGas = Boolean(getEnvConfiguredScriptUrl());
    let token: string | null = null;
    if (targetId) {
      try {
        token = await getAccessToken();
        if (hasGas || token) {
          await syncExamsOnlyToSpreadsheet(token, targetId, updatedExams);
          showToast(`✅ 已同步更新 Google 試算表 quiz_bank_publish 與 quiz_bank_unpublish！`, 'success');
        }
      } catch (err: any) {
        console.warn('Sync published exams error:', err);
      }
    }
    await recordAuditLog(logEntry, token);
  };

  // Exam created from modal - directly written to Google Sheet quiz_bank_publish or quiz_bank_unpublish
  const handleExamCreated = async (newExam: ExamPaper) => {
    setExamPapers((prev) => [newExam, ...prev]);

    const targetId = connectedSpreadsheetId || envSheetId;
    const targetTable = newExam.status === 'published' ? 'quiz_bank_publish' : 'quiz_bank_unpublish';
    const targetTableName = newExam.status === 'published' ? '公用試卷資料表' : '草稿資料表';

    const now = formatSheetTimestamp();
    const logEntry: AuditLog = {
      id: `#LOG-${Date.now().toString().slice(-6)}`,
      action: `題庫組卷建立試卷 [${newExam.id}] (${newExam.status === 'published' ? '發布' : '草稿'})`,
      target: `${newExam.title} (${targetTableName})`,
      operator: currentOperatorName,
      timestamp: now,
      status: 'success',
    };

    if (!targetId) {
      await recordAuditLog(logEntry);
      showToast(`試卷 ${newExam.id} 已建立 (未設定 Google 試算表，未寫入雲端)`);
      return;
    }

    try {
      const hasGas = Boolean(getEnvConfiguredScriptUrl());
      let token = await getAccessToken();
      if (!hasGas && !token) {
        showToast('正在開啟 Google 授權視窗，請允許寫入試算表...', 'info');
        const signRes = await googleSignIn();
        token = signRes?.accessToken || null;
      }

      if (hasGas || token) {
        showToast(`正在將考卷 ${newExam.id} 寫入 Google 試算表 (${targetTable})...`, 'info');
        const nextRowIdx = examPapers.filter((e) => e.status === newExam.status).length + 1;
        await appendExamToSpreadsheet(token, targetId, newExam, nextRowIdx);
        await recordAuditLog(logEntry, token);
        showToast(`✅ 考卷 ${newExam.id} 已成功寫入 Google 試算表「${targetTableName}」與 log 分頁！`, 'success');
      } else {
        await recordAuditLog(logEntry);
        showToast(`考卷 ${newExam.id} 已建立，但尚未設定 NEXT_PUBLIC_GOOGLE_SCRIPT_URL，未能寫入雲端`, 'warning');
      }
    } catch (err: any) {
      console.error('Error appending exam to Google Sheets:', err);
      await recordAuditLog(logEntry);
      showToast(`寫入 Google 試算表失敗: ${err.message || '請確認 NEXT_PUBLIC_GOOGLE_SCRIPT_URL 設定'}`, 'error');
    }
  };

  // Question save (create or update) - directly written to Google Sheet test_bank
  const handleSaveQuestion = async (q: Question) => {
    setQuestions((prev) => {
      const idx = prev.findIndex((item) => item.id === q.id);
      if (idx >= 0) {
        const copy = [...prev];
        copy[idx] = q;
        return copy;
      }
      return [q, ...prev];
    });

    const targetId = connectedSpreadsheetId || envSheetId;

    const now = formatSheetTimestamp();
    const logEntry: AuditLog = {
      id: `#LOG-${Date.now().toString().slice(-6)}`,
      action: '新增/更新試題並寫入 Google 試算表',
      target: `${q.id} (test_bank)`,
      operator: currentOperatorName,
      timestamp: now,
      status: 'success',
    };

    if (!targetId) {
      await recordAuditLog(logEntry);
      showToast(`題目 ${q.id} 已儲存 (未設定 Google 試算表，未寫入雲端)`);
      return;
    }

    try {
      const hasGas = Boolean(getEnvConfiguredScriptUrl());
      let token = await getAccessToken();
      if (!hasGas && !token) {
        showToast('正在開啟 Google 授權視窗，請允許寫入試算表...', 'info');
        const signRes = await googleSignIn();
        token = signRes?.accessToken || null;
      }

      if (hasGas || token) {
        showToast(`正在將題目 ${q.id} 寫入 Google 試算表 (test_bank)...`, 'info');
        const nextRowIdx = questions.length + 1;
        await appendQuestionToSpreadsheet(token, targetId, q, nextRowIdx);
        await recordAuditLog(logEntry, token);
        showToast(`✅ 題目 ${q.id} 已成功寫入 Google 試算表 test_bank 與 log 資料表！`, 'success');
      } else {
        await recordAuditLog(logEntry);
        showToast(`題目 ${q.id} 已建立，但尚未設定 NEXT_PUBLIC_GOOGLE_SCRIPT_URL，未能寫入雲端`, 'warning');
      }
    } catch (err: any) {
      console.error('Error appending question to Google Sheets:', err);
      await recordAuditLog(logEntry);
      showToast(`寫入 Google 試算表失敗: ${err.message || '請確認 NEXT_PUBLIC_GOOGLE_SCRIPT_URL 設定'}`, 'error');
    }
  };

  // Export actions
  const handleExportReport = () => {
    showToast('已匯出全校試卷評量與題庫統計報表 (Excel / CSV)！');
  };

  const handleBatchExportExams = () => {
    showToast(`已啟動 ${selectedExamIds.length} 份試卷之批次匯出 (PDF/Word 卷卡壓縮檔)！`);
  };

  const handleExportSingleExam = (format: 'pdf' | 'word') => {
    showToast(`已成功產生並下載 ${previewingExam?.id} 之 ${format.toUpperCase()} 試卷檔！`);
  };

  // Items to show in delete modal
  const deleteModalItems: DeleteItem[] = singleItemToDelete
    ? [singleItemToDelete]
    : deleteTargetType === 'exam'
    ? selectedExamIds.map((id) => {
        const ep = examPapers.find((e) => e.id === id);
        return {
          id,
          title: ep?.title || id,
          extraInfo: ep?.status === 'published' ? `已發布 / ${ep.examineeCount || 0}人應試` : `草稿 / ${ep?.questionCount || 0}題`,
        };
      })
    : selectedQuestionIds.map((id) => {
        const q = questions.find((item) => item.id === id);
        return {
          id,
          title: q?.content || id,
          extraInfo: `${q?.points || 0}分 / 難度 ${q?.difficultyScore ?? 3}`,
        };
      });

  const handleLoginSuccess = (user: UserProfile, roleInfo?: RoleItem) => {
    setCurrentUser(user);
    if (typeof window !== 'undefined') {
      sessionStorage.setItem('exam_logged_in_user', JSON.stringify(user));
    }
    const roleLabel = roleInfo?.name || user.roleName || user.role;

    // 依使用者規格：非管理員角色直接用 else 進行判斷
    const currentIsAdmin = String(user.role || '').toUpperCase() === 'ADMIN';
    if (currentIsAdmin) {
      setActivePage('question-bank');
    } else {
      setActivePage('user-exam-select');
    }

    showToast(
      `歡迎登入，${user.name || user.nickname}！角色身分：${roleLabel} (${user.role})`,
      'success'
    );
  };

  const handleSaveUserAccount = async (targetUser: UserProfile) => {
    setUsersList((prev) => {
      const idx = prev.findIndex((u) => u.identifier === targetUser.identifier || u.uuid === targetUser.uuid);
      if (idx >= 0) {
        const copy = [...prev];
        copy[idx] = targetUser;
        return copy;
      }
      return [targetUser, ...prev];
    });

    const targetId = connectedSpreadsheetId || envSheetId;
    const now = formatSheetTimestamp();
    const logEntry: AuditLog = {
      id: `#LOG-USR-${Date.now().toString().slice(-4)}`,
      action: `新增/更新使用者帳號「${targetUser.identifier}」`,
      target: `${targetUser.identifier} (users)`,
      operator: currentOperatorName,
      timestamp: now,
      status: 'success',
    };

    if (targetId) {
      try {
        const hasGas = Boolean(getEnvConfiguredScriptUrl());
        let token = await getAccessToken();
        if (!hasGas && !token) {
          showToast('正在開啟 Google 授權視窗，請允許寫入試算表...', 'info');
          const signRes = await googleSignIn();
          token = signRes?.accessToken || null;
        }

        if (hasGas || token) {
          const nextRowIdx = usersList.length + 1;
          await appendUserToSpreadsheet(token, targetId, targetUser, nextRowIdx);
          await recordAuditLog(logEntry, token);
          showToast(`✅ 帳號「${targetUser.identifier}」已成功寫入 Google 試算表 users 資料表！`, 'success');
        } else {
          await recordAuditLog(logEntry);
          showToast(`帳號「${targetUser.identifier}」已於前端建立，但尚未設定 NEXT_PUBLIC_GOOGLE_SCRIPT_URL，未能寫入雲端`, 'warning');
        }
      } catch (err: any) {
        console.error('Error appending user to Google Sheets:', err);
        await recordAuditLog(logEntry);
        showToast(`寫入 Google 試算表失敗: ${err.message || '請確認試算表寫入權限'}`, 'error');
      }
    } else {
      await recordAuditLog(logEntry);
      showToast(`帳號已更新 (本機暫存)`);
    }
  };

  const handleUpdateSelfProfile = (updated: Partial<UserProfile>) => {
    setCurrentUser((prev) => {
      if (!prev) return null;
      const merged = { ...prev, ...updated };
      if (typeof window !== 'undefined') {
        sessionStorage.setItem('exam_logged_in_user', JSON.stringify(merged));
      }
      return merged;
    });
    showToast('已成功更新個人資料設定！', 'success');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    if (typeof window !== 'undefined') {
      sessionStorage.removeItem('exam_logged_in_user');
    }
    showToast('已成功登出系統，請重新驗證身分。', 'info');
  };

  if (!currentUser) {
    if (authMode === 'register') {
      return (
        <RegisterPage
          onRegisterSuccess={(newUser) => {
            showToast(`帳號「${newUser.identifier}」註冊成功，歡迎使用！`, 'success');
            handleLoginSuccess(newUser);
          }}
          onNavigateToLogin={() => setAuthMode('login')}
          spreadsheetId={connectedSpreadsheetId || envSheetId}
        />
      );
    }

    return (
      <LoginPage
        onLoginSuccess={handleLoginSuccess}
        onNavigateToRegister={() => setAuthMode('register')}
        spreadsheetId={connectedSpreadsheetId || envSheetId}
      />
    );
  }

  // 若處於線上作答模式，獨立渲染 ExamClient 考試作答介面
  if (takingExamId) {
    if (activeExam) {
      return (
        <div className="min-h-screen bg-[#f8fafc]">
          <ExamClient exam={activeExam} />
        </div>
      );
    }
    return (
      <div className="grid min-h-screen place-items-center text-sm text-[#5b6673] bg-[#f8fafc]">
        <div className="flex flex-col items-center gap-3">
          <div className="h-9 w-9 animate-spin rounded-full border-4 border-[#2f5597] border-t-transparent"></div>
          <span className="font-medium text-slate-700">正在載入試卷題目與線上作答環境…</span>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f7f9fb] text-[#191c1e] font-sans antialiased">
      {/* Global Topbar Header */}
      <Header
        onOpenSearch={() => setIsGlobalSearchOpen(true)}
        onLogout={handleLogout}
        currentUser={currentUser}
        notifications={notifications}
        onMarkNotificationRead={(id) => {
          setNotifications((prev) =>
            prev.map((n) => (n.id === id ? { ...n, read: true } : n))
          );
        }}
      />

      {/* Left Sidebar */}
      <Sidebar
        activePage={activePage}
        selectedSubject={selectedSubject}
        onSelectSubject={(id) => {
          setSelectedSubject(id);
          setActivePage('question-bank');
        }}
        onNavigate={(page) => setActivePage(page)}
        onOpenCreateQuestion={() => {
          setEditingQuestion(null);
          setIsCreateQuestionOpen(true);
        }}
        onOpenUploadExam={() => setIsUploadExamOpen(true)}
        collapsed={collapsedSidebar}
        onToggleCollapse={() => setCollapsedSidebar(!collapsedSidebar)}
        questions={questions}
        categories={categories}
        isSheetsConnected={isOnline && hasSyncedSheet && !!connectedSpreadsheetId}
        spreadsheetUrl={connectedSpreadsheetUrl}
        onSync={() => handleBidirectionalSync(false)}
        isSyncing={isLoadingSheetData}
        currentUser={currentUser}
        onDownloadOfflinePack={handleDownloadOfflinePack}
        isDownloadingOfflinePack={isDownloadingOfflinePack}
        isOnline={isOnline}
      />

      {/* Main Content Viewport */}
      <div
        className={`${
          collapsedSidebar ? 'pl-16' : 'pl-64'
        } transition-all duration-150`}
      >
        <main className="w-full pt-18 px-6 pb-12 bg-[#f7f9fb] min-h-screen">
          {activePage === 'exam-papers' && (
            <ExamPapersView
              examPapers={examPapers}
              selectedExamIds={selectedExamIds}
              onToggleSelectExam={(id) => {
                setSelectedExamIds((prev) =>
                  prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id]
                );
              }}
              onSelectAllExams={(ids) => setSelectedExamIds(ids)}
              onClearExamSelection={() => setSelectedExamIds([])}
              onOpenCreateExamModal={() => {
                setSelectedSubject('math');
                setIsExamGenerationOpen(true);
              }}
              onOpenBatchDeleteModal={handleOpenBatchDeleteExams}
              onPreviewExam={(exam) => setPreviewingExam(exam)}
              onDeleteSingleExam={handleOpenSingleDeleteExam}
              onExportReport={handleExportReport}
              onBatchExport={handleBatchExportExams}
              onPublishExams={handlePublishExams}
            />
          )}

          {activePage === 'question-bank' && (
            <QuestionBankView
              subjectId={selectedSubject}
              questions={questions}
              selectedQuestionIds={selectedQuestionIds}
              onToggleSelectQuestion={(id) => {
                setSelectedQuestionIds((prev) =>
                  prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id]
                );
              }}
              onSelectAllQuestions={(ids) => setSelectedQuestionIds(ids)}
              onClearSelection={() => setSelectedQuestionIds([])}
              onOpenCreateModal={() => {
                setEditingQuestion(null);
                setIsCreateQuestionOpen(true);
              }}
              onOpenExamModal={() => setIsExamGenerationOpen(true)}
              onOpenBatchDeleteModal={handleOpenBatchDeleteQuestions}
              onViewQuestion={(q) => setPreviewingQuestion(q)}
              onEditQuestion={(q) => {
                setEditingQuestion(q);
                setIsCreateQuestionOpen(true);
              }}
              onDeleteQuestion={handleOpenSingleDeleteQuestion}
              isLoadingData={isLoadingSheetData}
            />
          )}

          {activePage === 'system-settings' && (
            <SystemSettingsView auditLogs={auditLogs} />
          )}

          {/* 管理員介面：帳號管理 (table: users) */}
          {activePage === 'account-manage' && (
            <AccountManagementView
              users={usersList}
              roles={rolesList}
              isLoading={isLoadingSheetData}
              onRefresh={() => handleFetchSpreadsheetData(false)}
              onSaveUser={handleSaveUserAccount}
            />
          )}

          {/* 使用者介面：1. 試卷選擇頁面 */}
          {activePage === 'user-exam-select' && (
            <div className="flex flex-col gap-5 max-w-6xl mx-auto">
              <ExamPaperSelection
                papers={examPapers}
                currentUser={currentUser}
                onNavigate={(page) => setActivePage(page as AppPageId)}
                onStartExam={(paper) => {
                  setTakingExamId(paper.id);
                  if (typeof window !== 'undefined') {
                    window.history.pushState(null, '', `/exam/${encodeURIComponent(paper.id)}`);
                  }
                }}
              />
            </div>
          )}

          {/* 使用者介面：2. 題目選擇頁面 (自選與公用題庫) */}
          {activePage === 'user-selector' && (
            <div className="flex flex-col gap-5 max-w-6xl mx-auto">
              <QuestionSelectorPage
                questions={questions}
                currentUser={currentUser}
                onNavigate={(page) => setActivePage(page as AppPageId)}
              />
            </div>
          )}

          {/* 使用者介面：3. 錯題匯入頁面 (歷年弱點趨勢分析) */}
          {activePage === 'user-wrong-questions' && (
            <div className="flex flex-col gap-5 max-w-6xl mx-auto">
              <WrongQuestionsPage
                currentUser={currentUser}
                onNavigate={(page) => setActivePage(page as AppPageId)}
              />
            </div>
          )}

          {/* 使用者介面：4. 個人設定 (個人資料與 Google Sheet 綁定) */}
          {activePage === 'user-settings' && currentUser && (
            <UserSettingsView
              currentUser={currentUser}
              onUpdateProfile={handleUpdateSelfProfile}
            />
          )}
        </main>
      </div>

      {/* Two-Phase High Risk Delete Confirmation Modal (Phase 1 & Phase 2) */}
      <TwoPhaseDeleteModal
        isOpen={isTwoPhaseDeleteOpen}
        onClose={() => setIsTwoPhaseDeleteOpen(false)}
        onConfirmSuccess={handleConfirmDeletion}
        items={deleteModalItems}
        itemTypeLabel={deleteTargetType === 'exam' ? '份試卷' : '筆題目'}
      />

      {/* Exam Generation Modal (Step 1 & Step 2) */}
      <ExamGenerationModal
        isOpen={isExamGenerationOpen}
        onClose={() => setIsExamGenerationOpen(false)}
        selectedQuestions={questions.filter((q) =>
          selectedQuestionIds.includes(q.id)
        )}
        onExamCreated={handleExamCreated}
      />

      {/* Question Detail Preview Modal */}
      <QuestionDetailModal
        question={previewingQuestion}
        onClose={() => setPreviewingQuestion(null)}
        onEdit={(q) => {
          setEditingQuestion(q);
          setIsCreateQuestionOpen(true);
        }}
      />

      {/* Create / Edit Question Modal */}
      <CreateQuestionModal
        isOpen={isCreateQuestionOpen}
        onClose={() => {
          setIsCreateQuestionOpen(false);
          setEditingQuestion(null);
        }}
        onSave={handleSaveQuestion}
        initialQuestion={editingQuestion}
        defaultSubjectId={selectedSubject === 'all' ? 'math' : selectedSubject}
      />

      {/* Upload Full Exam Paper Modal */}
      <UploadExamModal
        isOpen={isUploadExamOpen}
        onClose={() => setIsUploadExamOpen(false)}
        onUploadSuccess={async (importedQuestions, file) => {
          setQuestions((prev) => [...importedQuestions, ...prev]);
          setSelectedSubject('all');
          setActivePage('question-bank');
          showToast(
            `✅ 上傳成功！「${file.name}」通過審查，已匯入 ${importedQuestions.length} 筆題目。`,
            'success'
          );

          const targetId = connectedSpreadsheetId || envSheetId;
          const now = formatSheetTimestamp();
          const logEntry: AuditLog = {
            id: `#LOG-UPL-${Date.now().toString().slice(-4)}`,
            action: `上傳整份試卷匯入題庫 (${importedQuestions.length} 題)`,
            target: `${file.name} (test_bank)`,
            operator: currentOperatorName,
            timestamp: now,
            status: 'success',
          };

          if (targetId) {
            try {
              const hasGas = Boolean(getEnvConfiguredScriptUrl());
              let token = await getAccessToken();
              if (!hasGas && !token) {
                const signRes = await googleSignIn();
                token = signRes?.accessToken || null;
              }
              if (hasGas || token) {
                let rowOffset = questions.length + 1;
                for (const q of importedQuestions) {
                  await appendQuestionToSpreadsheet(token, targetId, q, rowOffset++);
                }
                await recordAuditLog(logEntry, token);
                showToast(
                  `✅ 已將「${file.name}」的 ${importedQuestions.length} 筆題目同步寫入 Google 試算表 test_bank！`,
                  'success'
                );
              }
            } catch (err) {
              console.warn('Error writing uploaded questions to Google Sheets:', err);
            }
          } else {
            await recordAuditLog(logEntry);
          }
        }}
      />

      {/* Exam Paper Preview & Export Modal */}
      <ExamPaperPreviewModal
        exam={previewingExam}
        onClose={() => setPreviewingExam(null)}
        questions={questions}
        onExport={handleExportSingleExam}
      />

      {/* ⌘K Global Quick Search Modal */}
      <GlobalSearchModal
        isOpen={isGlobalSearchOpen}
        onClose={() => setIsGlobalSearchOpen(false)}
        questions={questions}
        examPapers={examPapers}
        onSelectQuestion={(q) => {
          setSelectedSubject(q.subjectId);
          setActivePage('question-bank');
          setPreviewingQuestion(q);
        }}
        onSelectExam={(exam) => {
          setActivePage('exam-papers');
          setPreviewingExam(exam);
        }}
      />

      {/* 雙向比對衝突處理彈窗 */}
      <SyncConflictModal
        isOpen={conflictModalOpen}
        conflict={currentConflict}
        onClose={() => {
          setConflictModalOpen(false);
          setCurrentConflict(null);
        }}
        onResolvePersonalConflict={handleResolvePersonalConflict}
        onResolvePublicConflict={handleResolvePublicConflict}
        isProcessing={isResolvingConflict}
      />

      {/* Floating Toast Notification */}
      {toastMessage && (
        <div className="fixed bottom-6 right-6 z-50 bg-[#191c1e] text-white px-4 py-2.5 rounded-lg shadow-xl text-[13px] font-medium flex items-center gap-2 border border-[#434655]/40 animate-in fade-in slide-in-from-bottom-2">
          <span className="material-symbols-outlined text-[#6ffbbe] text-[18px]">info</span>
          <span>{toastMessage}</span>
        </div>
      )}
    </div>
  );
}
